        por_nome = [f for f in por_conteudo if _casa_nome(p, cfg[f])]
        return (por_nome or por_conteudo)[0]
    por_nome = [f for f in fontes if _casa_nome(p, cfg[f])]
    return por_nome[0] if por_nome else None


